        int n = Integer.parseInt(tokens[0]);
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) arr[i] = Integer.parseInt(tokens[1 + i]);
        int target = Integer.parseInt(tokens[1 + n]);
        long result = solve(arr, target);
        System.out.println(result);
